Unngå å bruke bare `except:` uten å spesifisere feiltypen. Det kan skjule uventede feil og gjøre debugging mye vanskeligere:

```python
# DÅRLIG - fanger alle feil, inkludert feil du ikke forventer
try:
    resultat = beregn_noe()
except:
    print("Noe gikk galt")

# BRA - fanger bare de feilene du forventer
try:
    resultat = beregn_noe()
except ValueError:
    print("Ugyldig verdi")
except ZeroDivisionError:
    print("Kan ikke dele på null")
```

exercises.solution:
```python
import random

def hent_gjetting():
    """Ber om en gyldig gjetting mellom 1 og 100."""
    while True:
        try:
            gjetting = int(input("Din gjetting (1-100): "))
            if gjetting < 1 or gjetting > 100:
                print("Tallet må være mellom 1 og 100!")
                continue
            return gjetting
        except ValueError:
            print("Ugyldig! Skriv inn et helt tall.")

def gi_hint(gjetting, fasit):
    """Gir hint basert på gjettingen."""
    if gjetting < fasit:
        print("For lavt! Prøv et høyere tall.")
        return False
    elif gjetting > fasit:
        print("For høyt! Prøv et lavere tall.")
        return False
    else:
        return True

def spill():
    """Hovedspilllogikken."""
    fasit = random.randint(1, 100)
    forsok = 0

    print("=== Gjettespill ===")
    print("Jeg tenker på et tall mellom 1 og 100.")

    while True:
        gjetting = hent_gjetting()
        forsok += 1

        if gi_hint(gjetting, fasit):
            print(f"Riktig! Du gjettet det på {forsok} forsøk!")
            if forsok <= 5:
                print("Imponerende!")
            elif forsok <= 10:
                print("Bra jobbet!")
            else:
                print("Du klarte det til slutt!")
            break

spill()
```

Programmet bruker tre funksjoner med tydelige ansvarsområder. hent_gjetting() sikrer gyldig input med try/except og validering. gi_hint() gir feedback. spill() styrer spillets gang.
